nodeTypes.inlineCode:
/* Hall transducer: offset + LSB quantization + range clamp; on Rail >= 0.5
 * the recorded isolated-rail-collapse artifact (RailVal_A) is emitted
 * verbatim, bypassing quantization AND the range clamp (recorded artifact
 * values sit outside the healthy range, twin/plant _rail_val). */
if (Rail >= 0.5) {
    I_Meas = (double)RailVal_A;
} else {
    const double x = I_True + Offset_A;
    /* nearest-even ties (rint): matches python round() at exact half-LSB */
    I_Meas = fmin((double)Range_A, fmax(-(double)Range_A, rint(x / (double)Lsb_A) * (double)Lsb_A));
}

/* Dyno: the host assigns state Rpm (or the default stands); convert. */
Omega_Elec = Rpm * (2.0 * M_PI / 60.0) * Poles;
Elec_Rpm = Rpm * Poles;

nodeTypes.constructorCode:
/* PMSM constructor: seed the integrator state from parameters. */
Id = Id0;
Iq = Iq0;
ThetaE = Theta0;

nodeTypes.inlineCode:
/* PMa-SyRM (hybrid PM-assisted synchronous reluctance) dq-Euler integration.
 * Physics is byte-equivalent to Plant.Machine.PmsmDq (twin/plant/plant.py
 * semantics): the hybrid is the standard PM-in-a-salient-frame form; the
 * reluctance product (Ld-Lq)*Id*Iq carries most of the torque in SyRM class
 * machines. This header comment only is different - never edit the equations
 * away from PmsmDq's.
 * Runtime symbols: only parameters/substituted ports and `DtPlant` (the host
 * substep). `OpenGates` is an optional input port (default 0).
 *
 * Ordering rules (validated by twin/plantgraph/proof_bench_parity.py):
 *   - ALL derivatives are computed from the PRE-update state, then assigned
 *     (assigning Id before computing dIq breaks bit-comparability), and
 *   - abc/torque outputs are rebuilt from the FINAL (id, iq, theta) of the
 *     substep (the plant measurement view is instantaneous with the
 *     reported state), and
 *   - P_Elec is zero when the gates are open (the collapse returns energy
 *     via the machine state decay itself, not the air-gap power term).
 */

double ct = cos((double)ThetaE);
double st = sin((double)ThetaE);

double valpha = (2.0 / 3.0) * (V_U - 0.5 * (V_V + V_W));
double vbeta  = (2.0 / 3.0) * (M_SQRT3 / 2.0) * (V_V - V_W);
double vd = ct * valpha + st * vbeta;
double vq = -st * valpha + ct * vbeta;

if (OpenGates >= 0.5) {
    /* six-switch-open: antiparallel diodes only conduct toward the link and
     * only when EMF overcomes it; the twin models the whole open state as an
     * exponential freewheel collapse (~1-2 ms), matching recorded telemetry
     * windows of the gate-kill tests (20/21). */
    double tau_open = 2.0e-3;
    Id -= Id * DtPlant / tau_open;
    Iq -= Iq * DtPlant / tau_open;
} else {
    double did = (vd - Rs * Id + Omega_Elec * Lq * Iq) / Ld;
    double diq = (vq - Rs * Iq - Omega_Elec * (Ld * Id + Lambda)) / Lq;
    Id += did * DtPlant;
    Iq += diq * DtPlant;
}
ThetaE = fmod((double)ThetaE + Omega_Elec * DtPlant, 2.0 * M_PI);
if (ThetaE < 0.0) ThetaE += 2.0 * M_PI;

// physical state rails (matches twin/plant.py)
Id = fmin(2000.0, fmax(-2000.0, Id));
Iq = fmin(2000.0, fmax(-2000.0, Iq));

Torque = 1.5 * Poles * (Lambda * Iq + (Ld - Lq) * Id * Iq);
P_Elec = (OpenGates >= 0.5) ? 0.0 : Torque * Omega_Elec / Poles;

// abc outputs from the FINAL (id, iq, theta) this step (sensor instant)
double ct2 = cos((double)ThetaE);
double st2 = sin((double)ThetaE);
I_U = ct2 * Id - st2 * Iq;
I_V = cos((double)ThetaE - 2.0 * M_PI / 3.0) * Id - sin((double)ThetaE - 2.0 * M_PI / 3.0) * Iq;
I_W = -I_U - I_V;

nodeTypes.constructorCode:
/* PMSM constructor: seed the integrator state from parameters. */
Id = Id0;
Iq = Iq0;
ThetaE = Theta0;

nodeTypes.inlineCode:
/* PMSM dq-Euler integration (exactly twin/plant/plant.py semantics).
 * Runtime symbols: only parameters/substituted ports and `DtPlant` (the host
 * substep). `OpenGates` is an optional input port (default 0).
 *
 * Ordering rules (validated by twin/plantgraph/proof_bench_parity.py):
 *   - ALL derivatives are computed from the PRE-update state, then assigned
 *     (assigning Id before computing dIq breaks bit-comparability), and
 *   - abc/torque outputs are rebuilt from the FINAL (id, iq, theta) of the
 *     substep (the plant measurement view is instantaneous with the
 *     reported state), and
 *   - P_Elec is zero when the gates are open (the collapse returns energy
 *     via the machine state decay itself, not the air-gap power term).
 */

double ct = cos((double)ThetaE);
double st = sin((double)ThetaE);

double valpha = (2.0 / 3.0) * (V_U - 0.5 * (V_V + V_W));
double vbeta  = (2.0 / 3.0) * (M_SQRT3 / 2.0) * (V_V - V_W);
double vd = ct * valpha + st * vbeta;
double vq = -st * valpha + ct * vbeta;

if (OpenGates >= 0.5) {
    /* six-switch-open: antiparallel diodes only conduct toward the link and
     * only when EMF overcomes it; the twin models the whole open state as an
     * exponential freewheel collapse (~1-2 ms), matching recorded telemetry
     * windows of the gate-kill tests (20/21). */
    double tau_open = 2.0e-3;
    Id -= Id * DtPlant / tau_open;
    Iq -= Iq * DtPlant / tau_open;
} else {
    double did = (vd - Rs * Id + Omega_Elec * Lq * Iq) / Ld;
    double diq = (vq - Rs * Iq - Omega_Elec * (Ld * Id + Lambda)) / Lq;
    Id += did * DtPlant;
    Iq += diq * DtPlant;
}
ThetaE = fmod((double)ThetaE + Omega_Elec * DtPlant, 2.0 * M_PI);
if (ThetaE < 0.0) ThetaE += 2.0 * M_PI;

// physical state rails (matches twin/plant.py)
Id = fmin(2000.0, fmax(-2000.0, Id));
Iq = fmin(2000.0, fmax(-2000.0, Iq));

Torque = 1.5 * Poles * (Lambda * Iq + (Ld - Lq) * Id * Iq);
P_Elec = (OpenGates >= 0.5) ? 0.0 : Torque * Omega_Elec / Poles;

// abc outputs from the FINAL (id, iq, theta) this step (sensor instant)
double ct2 = cos((double)ThetaE);
double st2 = sin((double)ThetaE);
I_U = ct2 * Id - st2 * Iq;
I_V = cos((double)ThetaE - 2.0 * M_PI / 3.0) * Id - sin((double)ThetaE - 2.0 * M_PI / 3.0) * Iq;
I_W = -I_U - I_V;

/* Host: assigns this node's states pre-step per the scenario timeline
 * (RaiseFault(name, active)). Nothing here - emitter wires the state as
 * extern-writable. */

/* Duty + vdc -> phase-to-neutral-mid voltages with IGBT knee + deadtime +
 * Rce drop (exactly twin/plant/plant.py convention):
 *   leg switching node -> phase-to-mid: (d - d_avg)/50 * vdc
 *   error sign(i) * (v_ce0 + TdOverhead*vdc + r_ce*|i|) subtracted per phase.
 */

double d_avg = (Du + Dv + Dw) / 3.0;
double vu_raw = (Du - d_avg) / 50.0 * Vdc;
double vv_raw = (Dv - d_avg) / 50.0 * Vdc;
double vw_raw = (Dw - d_avg) / 50.0 * Vdc;

/* de-energized stage: legs float, all voltage views go to zero (the
 * twin's convention on gate kill) */
if (OpenGates >= 0.5) {
    vu_raw = vv_raw = vw_raw = 0.0;
}

/* pre-distortion command volts: the phase-ADC-visible view (the sensor
 * never sees the knee/deadtime/Rce error applied below) */
V_U_Raw = vu_raw;
V_V_Raw = vv_raw;
V_W_Raw = vw_raw;

auto phase = [&](double v_cmd, double i_p) -> double {
    if (fabs(i_p) < 1e-3) return v_cmd;
    double s_i = i_p > 0.0 ? 1.0 : -1.0;
    return v_cmd - s_i * (Vce0_V + TdOverhead * Vdc + Rce_Ohm * fabs(i_p));
};

if (OpenGates >= 0.5) {
    V_U = V_V = V_W = 0.0;
} else {
    V_U = phase(vu_raw, I_U);
    V_V = phase(vv_raw, I_V);
    V_W = phase(vw_raw, I_W);
}

/* Two-quadrant buck/boost cell (average model, mirrors the python
 * reference): effective leg voltage = duty * V_High with the knee-class
 * distortion, inductor integrates toward the low side minus winding Rs.
 * Outputs publish from the decaying inductor state even while gates are
 * open. `DtPlant` + ports + parameters are the only runtime symbols. */

double duty = fmin(100.0, fmax(0.0, (double)Duty)) / 100.0;

if (OpenGates >= 0.5) {
    double tau_open = 2.0e-3;
    I_L -= I_L * DtPlant / tau_open;
} else {
    double v_sw = duty * (double)V_High;
    double i = I_L;
    if (fabs(i) >= 1e-3) {
        double s_i = (i > 0.0) ? 1.0 : -1.0;
        v_sw -= s_i * ((double)Vce0_V + (double)TdOverhead * (double)V_High
                       + (double)Rce_Ohm * fabs(i));
    }
    I_L += (v_sw - (double)V_Low - (double)Rs_Winding * i) / (double)L_H * DtPlant;
    I_L = fmin(2000.0, fmax(-2000.0, I_L));
}

I_High = duty * I_L;
P_High = (double)V_High * I_High;
P_Draw = P_High;
I_Low = I_L;
P_Low = (double)V_Low * I_Low;
P_DrawLow = -P_Low;

nodeTypes.constructorCode:
/* SPMSM constructor: seed the integrator state from parameters. */
Id = Id0;
Iq = Iq0;
ThetaE = Theta0;

nodeTypes.inlineCode:
/* SPMSM dq-Euler (non-salient): identical form to Plant.Machine.PmsmDq with
 * Ld == Lq == L_H, torque strictly 1.5*pp*Lambda*iq. Only `DtPlant` + ports
 * + parameters are runtime symbols; ordering rules per the README ground
 * rules (derivatives pre-update; abc rebuilt from the final state). */

double ct = cos((double)ThetaE);
double st = sin((double)ThetaE);

double valpha = (2.0 / 3.0) * (V_U - 0.5 * (V_V + V_W));
double vbeta  = (2.0 / 3.0) * (M_SQRT3 / 2.0) * (V_V - V_W);
double vd = ct * valpha + st * vbeta;
double vq = -st * valpha + ct * vbeta;

if (OpenGates >= 0.5) {
    /* six-switch-open freewheel collapse (~1-2 ms evidence window) */
    double tau_open = 2.0e-3;
    Id -= Id * DtPlant / tau_open;
    Iq -= Iq * DtPlant / tau_open;
} else {
    double did = (vd - Rs * Id + Omega_Elec * L_H * Iq) / L_H;
    double diq = (vq - Rs * Iq - Omega_Elec * (L_H * Id + Lambda)) / L_H;
    Id += did * DtPlant;
    Iq += diq * DtPlant;
}
ThetaE = fmod((double)ThetaE + Omega_Elec * DtPlant, 2.0 * M_PI);
if (ThetaE < 0.0) ThetaE += 2.0 * M_PI;

Id = fmin(2000.0, fmax(-2000.0, Id));
Iq = fmin(2000.0, fmax(-2000.0, Iq));

Torque = 1.5 * Poles * Lambda * Iq;    // SPMSM: no reluctance term exists
P_Elec = (OpenGates >= 0.5) ? 0.0 : Torque * Omega_Elec / Poles;

double ct2 = cos((double)ThetaE);
double st2 = sin((double)ThetaE);
I_U = ct2 * Id - st2 * Iq;
I_V = cos((double)ThetaE - 2.0 * M_PI / 3.0) * Id - sin((double)ThetaE - 2.0 * M_PI / 3.0) * Iq;
I_W = -I_U - I_V;

nodeTypes.constructorCode:
/* DC bus constructor. */
Vdc = V0_V;
I_Link = 0.0;
P_Link = 0.0;

nodeTypes.inlineCode:
/* DC bus integrator (exactly twin/plant/plant.py bench-supply semantics):
 *   i_sup = (v_set - v)/r_s, clamped to [sink, i_limit]; optional CV clamp
 *   branch sinks above cv_clamp_v.
 *   C dv/dt = i_sup - i_inv;  i_inv = P_Draw / max(vdc, 1).
 *   physical rails clamp keeps solver sane at supply-collapse boundaries.
 */

double r_s = fmax((double)SeriesR_mOhm / 1e3, 1e-9);
double i_sup = ((double)VSet_V - Vdc) / r_s;
double lo = (CanSink >= 0.5) ? -SinkLimit_A : 0.0;
double hi = ILimit_A;
if (CvClamp_V > 0.0 && Vdc > CvClamp_V) {
    i_sup = -fmin((Vdc - (double)CvClamp_V) / r_s, (double)CvClampSink_A);
} else {
    i_sup = fmax(lo, fmin(i_sup, hi));
}
double i_inv = P_Draw / fmax((double)Vdc, 1.0);
Vdc += (i_sup - i_inv) / (double)Cap_F * DtPlant;
Vdc = fmin(fmax((double)Vdc, 0.5), 2000.0);

// regen-feed convention: positive = into the link (matches recorded dclink_*;
// twin/plant.py emits -p_dc / -p_dc/max(vdc,1) against the updated bus)
P_Link = -P_Draw;
I_Link = -P_Draw / fmax((double)Vdc, 1.0);

nodeTypes.constructorCode:
/* Two-node thermal constructor. */
T1 = T1_0_C;
T2 = T2_0_C;

nodeTypes.inlineCode:
/* Two-node Cauer chain + NTC spot-offset view (twin/plant semantics):
 *   dT1 = (P - (T1-T2)/R12) / C1
 *   dT2 = ((T1-T2)/R12 - (T2-TAmb)/R2) / C2
 */
T1 += (P_Heat - (T1 - T2) / (double)R12_KW) / (double)C1_JK * DtPlant;
T2 += ((T1 - T2) / (double)R12_KW - (T2 - (double)TAmb_C) / (double)R2_KW)
      / (double)C2_JK * DtPlant;

T_Plate = T1;
T_Sink = T2;
T_Meas1 = T1 + Off1;
/* ch2 NTC law (twin/plant/plant.py idle-warm artifact):
 *   t_plate + Off2Idle - Off2Slope * max(0, t_plate - (t_amb + Off2Knee)) */
T_Meas2 = T1 + Off2Idle
        - (double)Off2Slope * fmax(0.0, T1 - ((double)TAmb_C + (double)Off2Knee_C));
/* ch3: constant third spot (three-strip assemblies like the DSR bike rig) */
T_Meas3 = T1 + Off3;

/* Free shaft inertia: J dot(omega_mech)/dt = Torque - B*omega_mech
 * (state in RPM for readability; the table-lookup math: d(Rpm)/dt =
 * (Te - B*(K*Rpm)) / (J*K)+. */
const double K = 2.0 * M_PI / 60.0;
Rpm += ((double)Torque - (double)B * (K * Rpm)) / ((double)J) * (DtPlant / K);
Omega_Elec = Rpm * K * Poles;
Elec_Rpm = Rpm * Poles;

nodeTypes.constructorCode:
/* Induction constructor: all four dq states seed at zero. */
Isd = 0.0;
Isq = 0.0;
Ird = 0.0;
Irq = 0.0;

nodeTypes.inlineCode:
/* Induction machine in the STATIONARY frame (wf = 0): exactly
 * twin/plant/induction.py. Coupled-L solve per substep:
 *   psi_sd = lsg*isd + Lm*ird ; psi_rd = Lm*isd + lrg*ird  (same in q)
 *   [lsg Lm; Lm lrg][did dir] = [vs - Rs*is + wf*psi_other ...]
 *   w_slip = wf - Omega_M  (frame - machine elec speed)
 *   Te   = 1.5 * pp * (psi_rq*Isd - psi_rd*Isq)
 * With a 0-frame, the dq state IS stationary abc: I_U/alpha = Isd directly.
 */

double lsg = (double)Lls + (double)Lm;
double lrg = (double)Llr + (double)Lm;
double det = lsg * lrg - (double)Lm * (double)Lm;

double valpha = (2.0 / 3.0) * (V_U - 0.5 * (V_V + V_W));
double vbeta  = (2.0 / 3.0) * ((M_SQRT3 / 2.0) * (V_V - V_W));
double vd = valpha;
double vq = vbeta;

double wf = 0.0;                              // stationary frame
double w_slip = wf - (double)Omega_Elec;      // frame - machine elec speed

double psi_sd = lsg * Isd + (double)Lm * Ird;
double psi_sq = lsg * Isq + (double)Lm * Irq;
double psi_rd = (double)Lm * Isd + lrg * Ird;
double psi_rq = (double)Lm * Isq + lrg * Irq;

double bd0 = vd - (double)Rs * Isd + wf * psi_sq;
double bd1 = -(double)Rr * Ird + w_slip * psi_rq;
double bq0 = vq - (double)Rs * Isq - wf * psi_sd;
double bq1 = -(double)Rr * Irq - w_slip * psi_rd;

double did  = (bd0 * lrg - (double)Lm * bd1) / det;
double didr = (lsg * bd1 - (double)Lm * bd0) / det;
double diq  = (bq0 * lrg - (double)Lm * bq1) / det;
double diqr = (lsg * bq1 - (double)Lm * bq0) / det;

if (OpenGates >= 0.5) {
    /* six-switch-open freewheel collapse (twin/plant) */
    double tau_open = 2.0e-3;
    Isd -= Isd * DtPlant / tau_open;
    Isq -= Isq * DtPlant / tau_open;
    Ird -= Ird * DtPlant / tau_open;
    Irq -= Irq * DtPlant / tau_open;
} else {
    Isd += did * DtPlant;
    Ird += didr * DtPlant;
    Isq += diq * DtPlant;
    Irq += diqr * DtPlant;
}

// physical rails
Isd = fmin(2000.0, fmax(-2000.0, Isd));
Isq = fmin(2000.0, fmax(-2000.0, Isq));
Ird = fmin(2000.0, fmax(-2000.0, Ird));
Irq = fmin(2000.0, fmax(-2000.0, Irq));

Torque = 1.5 * Poles * (psi_rd * Isq - psi_rq * Isd);
// air-gap (link-side) power = Te * syn speed: nomenclature plant.py; the
// synchronous speed is a controller-side external (unwired = 0, matching
// the python zero-binding), gated to zero while gates are open
P_Elec = (OpenGates >= 0.5) ? 0.0 : Torque * Omega_Cmd / Poles;

// abc stator currents at the stationary frame: alpha := U directly
I_U = Isd;
I_V = -0.5 * Isd + (M_SQRT3 / 2.0) * Isq;
I_W = -I_U - I_V;

/* Fitted total-loss law (twin/plant/plant.py v2; calibrated 2026-10-20).
 * `Idle` is zero-bound by default when unconnected = 'live' (losses on).
 * Domain guard: floor at 0 - the polynomial is a data-law over the fitted
 * campaign span and extrapolates negative at induction-idle points; the
 * floor prevents energy-creation artifacts. */
double idle = Idle;   // optional-wired; 0 = live (default), >=0.5 = gates off
double lt = (K1 * fabs(Im) + K2 * Im * Im + K3 * fabs(Om)
             + K4 * fabs(Im) * fabs(Om) + K5 * Vdc * fabs(Im));
if (idle >= 0.5) lt = 0.0;
if (lt < 0.0) {
    /* guard engagement is observability, not silence (python floor_hits) */
    FloorHits = FloorHits + 1.0;
    lt = 0.0;
}
P_Loss = lt;
// plate heat = share of the law + the idle heat floor while gates are live
// (bench aux residual, cal_log idle-warm anchor); zero when gates off
P_Plate = lt * PlateShare + (idle >= 0.5 ? 0.0 : (double)IdleHeat_W);

/* Sin/cos encode from true rotor angle (twin/plant semantics):
 *   phi_mech = (ThetaE - OffsetDeg_rad) / Poles
 *   sin_c = Mid + Amp*sin(phi), cos_c = Mid + Amp*cos(phi)
 * Disconnect rails both counts to 0 (hard pull). */
if (Disconnect >= 0.5) {
    Sin = 0.0;
    Cos = 0.0;
} else {
    double phi = ((double)ThetaE - (double)OffsetDeg * (double)(M_PI / 180.0)) / (double)Poles;
    /* python reference uses int() truncation (toward zero), not rounding;
     * keep all three engines bit-identical */
    Sin = (double)(int)((double)MidSin + (double)AmpSin * sin(phi));
    Cos = (double)(int)((double)MidCos + (double)AmpCos * cos(phi));
}

nodeTypes.constructorCode:
/* SRM constructor: winding currents seed at zero; rotor position from Theta0. */
I_U = 0.0;
I_V = 0.0;
I_W = 0.0;
ThetaE = (double)Theta0;

nodeTypes.inlineCode:
/* Switched reluctance machine: analytic macroscopic model (twin/plantgraph
 * class mirror). psi(i, theta) from aligned/unaligned curves with a
 * (1+cos(Nr*theta))/2 tooth profile; per-phase Kirchhoff integration with
 * the position-dependent incremental inductance and motion back-EMF; torque
 * is the analytic coenergy derivative (finite-difference validated to 1e-4).
 * Omega_Elec carries MECHANICAL rad/s in this template. */

/* aligned-phase flux map and its inductance:
 *   lambda_a(i) = LambdaSat * (1 - e^{-Ka*i}) ;
 *   d lambda_a/di = LambdaSat*Ka * e^{-Ka*i}        (L_unsat at i=0)     */
double la = 0.0, dla = 0.0;

for (int j = 0; j < 3; ++j) {
    double i = (j == 0) ? I_U : (j == 1) ? I_V : I_W;
    double v = (j == 0) ? V_U : (j == 1) ? V_V : V_W;
    double phi = j * (2.0 * M_PI) / (3.0 * RotorTeeth);
    double x = RotorTeeth * (ThetaE - phi);
    double f  = (1.0 + cos(x)) / 2.0;
    double fp = -RotorTeeth * sin(x) / 2.0;
    la  = LambdaSat * (1.0 - exp(-Ka * i));
    dla = LambdaSat * Ka * exp(-Ka * i);
    if (OpenGates >= 0.5) {
        double tau_open = 2.0e-3;
        i -= i * DtPlant / tau_open;
    } else {
        double l_inc = LU_H + (dla - LU_H) * f;
        double bemf  = (la - LU_H * i) * fp * Omega_Elec;
        double di    = (v - Rs * i - bemf) / fmax(l_inc, 1e-6);
        i += di * DtPlant;
    }
    i = fmin(2000.0, fmax(-2000.0, i));
    if (j == 0) I_U = i; else if (j == 1) I_V = i; else I_W = i;
}

ThetaE = fmod((double)ThetaE + Omega_Elec * DtPlant, 2.0 * M_PI);
if (ThetaE < 0.0) ThetaE += 2.0 * M_PI;

/* analytic coenergy torque over the phases */
Torque = 0.0;
PsiAligned = 0.0;
{
    double i_max = 0.0;
    for (int j = 0; j < 3; ++j) {
        double i = (j == 0) ? I_U : (j == 1) ? I_V : I_W;
        double phi = j * (2.0 * M_PI) / (3.0 * RotorTeeth);
        double x = RotorTeeth * (ThetaE - phi);
        double fp = -RotorTeeth * sin(x) / 2.0;
        double integ = LambdaSat * (i - (1.0 - exp(-Ka * i)) / Ka)
                     - LU_H * i * i / 2.0;
        Torque += fp * integ;
        i_max = fmax(i_max, i);
    }
    PsiAligned = LambdaSat * (1.0 - exp(-Ka * i_max));

    /* instantaneous winding input power; zero while gates open */
    P_Elec = (OpenGates >= 0.5) ? 0.0
                                : V_U * I_U + V_V * I_V + V_W * I_W;
}

/* Dual Active Bridge (average square-wave power law; combinational, mirrors
 * the python reference): P = V1 * V2' * phi * (pi - |phi|) / (2 pi^2 f L).
 * V2' is the LV voltage referred to the HV side (V_Low * Ratio_HL). */

if (OpenGates >= 0.5) {
    P_Transfer = 0.0;
    I_High = 0.0;
    I_Low = 0.0;
    P_DrawHigh = 0.0;
    P_DrawLow = 0.0;
} else {
    double phi = fmin(M_PI, fmax(-M_PI, (double)PhaseShift));
    double v1 = (double)V_High;
    double v2 = (double)V_Low * (double)Ratio_HL;   // LV side seen on HV swing
    if ((double)Lk_H <= 0.0 || (double)Fsw_Hz <= 0.0 || v1 <= 0.0 || v2 <= 0.0) {
        P_Transfer = 0.0;
        I_High = 0.0;
        I_Low = 0.0;
        P_DrawHigh = 0.0;
        P_DrawLow = 0.0;
    } else {
        P_Transfer = v1 * v2 * phi * (M_PI - fabs(phi))
                   / (2.0 * M_PI * M_PI * (double)Fsw_Hz * (double)Lk_H);
        I_High = P_Transfer / v1;
        /* receiver convention: the LV-side current flowing INTO the bridge;
         * while the HV side delivers (phi>0) the LV bus receives, and its
         * outflow is negative */
        I_Low = -P_Transfer / (double)V_Low;
    }
}
P_DrawHigh = P_Transfer;
P_DrawLow = -P_Transfer;

/* Isolated voltage sense: first-order lag then LSB quantization
 * (matches twin/plant's MAX22530 path). LagTau_S <= 0 = no lag (bus channel
 * on the 8 kHz AA filter is effectively lag-free at control rates). */
if (LagTau_S > 0.0) {
    Lag += ((double)V_True - Lag) * fmin(1.0, (double)DtPlant / (double)LagTau_S);
} else {
    Lag = (double)V_True;
}
V_Meas = rint(Lag / (double)Lsb_V) * (double)Lsb_V;   // nearest-even ties == python round()
